/**
 * Rail service worker — push delivery only.
 *
 * Deliberately does NOT cache anything. Rail is a live view of a bar's money
 * and stock; serving a stale cached dashboard would be worse than showing an
 * offline error. The only reason this worker exists is that Web Push requires
 * one.
 *
 * Hand-written rather than generated by next-pwa: the plugin's value is its
 * caching strategies, which are exactly what is not wanted here.
 */

self.addEventListener('install', () => {
  // Take over immediately rather than waiting for every old tab to close —
  // otherwise a push subscription can outlive the worker meant to handle it.
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener('push', (event) => {
  if (!event.data) return;

  let payload;
  try {
    payload = event.data.json();
  } catch {
    // A push whose body is not our JSON is not ours to render. Showing a
    // generic notification would be worse than showing none.
    return;
  }

  const { title, body, url, tag } = payload;
  if (!title) return;

  event.waitUntil(
    self.registration.showNotification(title, {
      body,
      // The notification id, so a re-push of the same alert replaces rather
      // than stacks.
      tag: tag || undefined,
      icon:  '/icon-192.png',
      badge: '/icon-192.png',
      data:  { url: url || '/app/dashboard' },
    }),
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const target = (event.notification.data && event.notification.data.url) || '/app/dashboard';

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clients) => {
      // Focus an existing Rail tab and navigate it, rather than opening a
      // fourth copy of the app every time a manager taps an alert.
      for (const client of clients) {
        if (client.url.includes('/app') && 'focus' in client) {
          client.navigate(target);
          return client.focus();
        }
      }
      return self.clients.openWindow(target);
    }),
  );
});
